CREATE TABLE IF NOT EXISTS users (id SERIAL PRIMARY KEY, phone_number VARCHAR(20) UNIQUE NOT NULL, email_address VARCHAR(255) UNIQUE NOT NULL, name VARCHAR(120), password_hash TEXT, language VARCHAR(10) DEFAULT 'en', has_mobile_app BOOLEAN DEFAULT false, created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS otp_sessions (id SERIAL PRIMARY KEY, phone_number VARCHAR(20) NOT NULL, otp_hash TEXT NOT NULL, expires_at TIMESTAMPTZ NOT NULL, verified BOOLEAN DEFAULT false, attempt_count INT DEFAULT 0);
CREATE TABLE IF NOT EXISTS emails (id SERIAL PRIMARY KEY, message_id TEXT UNIQUE NOT NULL, sender TEXT NOT NULL, subject TEXT NOT NULL, body TEXT NOT NULL, folder VARCHAR(20) DEFAULT 'inbox', is_read BOOLEAN DEFAULT false, thread_key TEXT NOT NULL, created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS email_recipients (id SERIAL PRIMARY KEY, email_id INT REFERENCES emails(id) ON DELETE CASCADE, recipient TEXT NOT NULL, type VARCHAR(3) NOT NULL CHECK (type IN ('TO','CC','BCC')));
CREATE TABLE IF NOT EXISTS aliases (id SERIAL PRIMARY KEY, user_id INT REFERENCES users(id) ON DELETE CASCADE, alias VARCHAR(255) UNIQUE NOT NULL, created_at TIMESTAMPTZ DEFAULT NOW());
